import{_ as i,P as o,d as s,e as r,x as t,q as n}from"./chunks/framework.BRr8VP3a.js";const b=JSON.parse('{"title":"Part 7 The Human Structured World","description":"","frontmatter":{"title":"Part 7 The Human Structured World","xkChars":0,"xkWords":6569,"xkLessons":{"7.2.4":{"title":"Uptake carriers are not automatically responsible parties","lead":"Doing, bearing costs, benefiting, deciding, and owing a remedy are distinct roles.","explanation":["CV identifies what actually executes, transmits, maintains, records, cares for, or repairs: a person, role, procedure, facility, or system. This makes otherwise invisible work and dependencies describable without assigning all responsibility to the carrier.","RS needs a separate basis, responsibility type, knowledge and control, scope, and period. Action, decision, authorization, supervision, benefit, and remedy can involve different parties. A low-authority executor must not become the default main responsible party merely because their action is most visible.","Separate cost bearers, beneficiaries, and the right to stop as well. A person’s demonstrated capacity to absorb work does not create an unlimited duty. A recommendation for better task allocation is an analytical result, not an authorization to impose the change."],"distinctions":[{"leftTitle":"Uptake carrier","leftText":"What performs or carries the relevant function.","rightTitle":"Responsible party","rightText":"Who bears a particular responsibility on independently established grounds."}],"teachingExamples":[{"title":"A repair worker and a maintenance budget","text":"Suppose a worker carries out repairs while a separate role controls staffing and preventive maintenance. Their actual actions, information, powers, and duties must be assessed individually; one visible action cannot settle the whole responsibility chain.","assumptions":"Hypothetical organization; no person or legal liability is identified.","boundary":"Specific legal and organizational duties require their own applicable rules."}],"boundaries":["Capacity does not establish an obligation to continue indefinitely.","The classification itself does not assign liability or authorize redistribution."],"questionAnswers":[{"question":"Can a technical facility carry a function without carrying moral responsibility?","answer":"Yes. Functional carrying and responsibility are different classifications; organizational subject status is also judged under its own rules.","basis":"Theory v2, §7.2.4, with the distinctions explained above."}],"caseLinks":[{"title":"Responsibility and actual work","href":"/en/concepts/responsibility"}],"sourceRefs":[{"section":"7.2.4","startLine":1594,"endLine":1597}],"sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","sources":[{"id":"theory-v2-en","title":"Xikari: On Conditions, Structure, and Transformation — English reference edition","url":"/en/theory/part-07#section-7-2-4","source_type":"theory_source","version_or_date":"Theory v2, November 2026","locator":"§7.2.4; English reading edition, lines 1594–1597","claim_support":["The section’s definitions, argument, and conditions, interpreted in this guide."],"limits":["The Chinese original remains authoritative. This is a theory source, not independent empirical support for a real case."]}]},"7.3.9":{"title":"Equal total hours can hide unequal usable time","lead":"Some tasks depend on continuous, predictable blocks, not just the sum of occupied hours.","explanation":["HV09 compares tasks and coordination requirements with available capacity and recovery margins at particular positions. When the inquiry concerns overall burden, execution, management, simultaneous activity, standby, and opportunity costs may require different measures. Adding unlike quantities into one burden score can conceal rather than clarify.","The v2 addition asks whether default-contact, standby, or last-minute replacement duties split the blocks needed for a task. Two people may each report the same total work hours while only one has predictable uninterrupted time for study, recovery, or a long task.","Record block length and predictability when the target actually depends on them. These are not extra occupied hours to add again to a time-use total. The relevant question is what task remains feasible under the observed temporal arrangement."],"distinctions":[{"leftTitle":"Total occupied time","leftText":"A quantity measured under stated counting and overlap rules.","rightTitle":"Continuous available blocks","rightText":"A different condition concerning length and predictability of usable intervals."}],"teachingExamples":[{"title":"Four hours in two schedules","text":"One person has a predictable four-hour block. Another has four nominally free hours repeatedly interruptible by standby calls. A task needing two uninterrupted hours may be feasible only in the first schedule.","assumptions":"Hypothetical task with a stated continuity requirement.","boundary":"The example does not assign a universal burden value to standby or convert availability into paid hours."}],"boundaries":["Only collect continuity information when it is relevant to the question.","An observed scheduling constraint does not establish personality, willingness, or a universal overload mechanism."],"questionAnswers":[{"question":"Should the lost continuous block be added as four more worked hours?","answer":"No. Preserve the distinct measures and overlap rules; evaluate continuity against the task that needs it.","basis":"Theory v2, §7.3.9, with the distinctions explained above."}],"caseLinks":[],"sourceRefs":[{"section":"7.3.9","startLine":1672,"endLine":1679}],"sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","sources":[{"id":"theory-v2-en","title":"Xikari: On Conditions, Structure, and Transformation — English reference edition","url":"/en/theory/part-07#section-7-3-9","source_type":"theory_source","version_or_date":"Theory v2, November 2026","locator":"§7.3.9; English reading edition, lines 1672–1679","claim_support":["The section’s definitions, argument, and conditions, interpreted in this guide."],"limits":["The Chinese original remains authoritative. This is a theory source, not independent empirical support for a real case."]}]},"7.6.1":{"title":"Allocation can shape the capability used to justify later allocation","lead":"A reinforcing loop requires evidence across rounds, not just a repeated claim of merit.","explanation":["An allocation of practice, opportunity, or responsibility can help form capability. Later allocation may then use that capability as a criterion, widening a gap or concentrating opportunities. This is a candidate mechanism with multiple links and at least two rounds to examine.","Check whether the relevant capability actually depends on practice and whether that practice is obtained mainly through the allocation in question. Then check whether current capability actually changes the next allocation. Prior differences, incentives, training duration, legal conditions, preferences, attrition, scarcity, discrimination, trust, and incumbents’ interests may provide competing or interacting explanations.","The gap or concentration must widen relative to the starting point, and capability formation, retention, and later use need evidence under §4.5. If material is insufficient, retain a candidate. Formal mechanism support additionally requires C10’s carrier-reproduction route; repeated association alone does not qualify.","The capability difference can be real even if its formation was unequal. Recognizing its reality does not establish fair opportunity or dictate a future allocation rule. Conversely, unequal allocation among equally capable people may challenge the proposed capability-to-allocation link and require a different mechanism.","Discriminating observations compare when the gap began, whether equally capable people receive comparable allocations, and whether predeclared, independently verifiable handover, training, or access conditions reduce the gap within a window appropriate to capability formation. Compare units with similarly tight resources but different allocation rules. Contrary observations require narrowing or withdrawing the affected link, not changing the meaning of genuine support after the outcome."],"distinctions":[{"leftTitle":"Measured capability","leftText":"A task-specific difference that may have evidence.","rightTitle":"Fair allocation","rightText":"A normative judgment about opportunities, criteria, burdens, and alternatives."}],"teachingExamples":[{"title":"Practice opportunities across two rounds","text":"Suppose group A receives practice, improves on a relevant task, and that measured improvement is used to assign the next practice round. Trace each link and compare competing explanations before calling this reinforcement.","assumptions":"Constructed mechanism candidate, not an observation of a real group.","boundary":"The pattern does not by itself prove malicious intent or justify equal or unequal allocation."}],"boundaries":["A loop cannot be established from one static association.","Capability, opportunity, authority, and normative justification require distinct evidence.","Support or training conditions used in a comparison must be stated beforehand and independently verifiable. A lack of improvement cannot be excused afterward by asserting that the offered conditions were not genuine."],"questionAnswers":[{"question":"Does a manager repeatedly saying “capability” establish the second link?","answer":"No. The criterion must actually affect the later allocation; rhetoric alone does not identify the mechanism.","basis":"Theory v2, §7.6.1, with the distinctions explained above."}],"caseLinks":[],"sourceRefs":[{"section":"7.6.1","startLine":1719,"endLine":1734}],"sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","sources":[{"id":"theory-v2-en","title":"Xikari: On Conditions, Structure, and Transformation — English reference edition","url":"/en/theory/part-07#section-7-6-1","source_type":"theory_source","version_or_date":"Theory v2, November 2026","locator":"§7.6.1; English reading edition, lines 1719–1734","claim_support":["The section’s definitions, argument, and conditions, interpreted in this guide."],"limits":["The Chinese original remains authoritative. This is a theory source, not independent empirical support for a real case."]}]}}},"headers":[],"relativePath":"en/theory/part-07.md","filePath":"en/theory/part-07.md"}'),c={name:"en/theory/part-07.md"};function l(d,e,u,p,h,m){const a=o("SectionLesson");return s(),r("div",null,[e[0]||(e[0]=t("",1)),n(a,{section:"7.2.4"}),e[1]||(e[1]=t("",1)),n(a,{section:"7.3.9"}),e[2]||(e[2]=t("",1)),n(a,{section:"7.6.1"}),e[3]||(e[3]=t("",3))])}const g=i(c,[["render",l]]);export{b as __pageData,g as default};
